files.content:
[hidden] { display: none !important; }

:root {
  --bg: #0f0f1a;
  --card: #1e1e2e;
  --primary: #89b4fa;
  --accent: #f38ba8;
  --text: #cdd6f4;
  --muted: #6c7086;
  --radius: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.board {
  background: var(--card);
  border: 4px solid var(--primary);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 0 0 4px var(--bg), 0 8px 24px rgba(0,0,0,0.6);
}

.title {
  text-align: center;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 24px;
}

.teams {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

.team {
  flex: 1;
  background: rgba(255,255,255,0.04);
  border: 2px solid var(--muted);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.team-name {
  font-size: 1rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.score {
  font-size: 3rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--primary);
  line-height: 1;
}

.buttons {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--bg);
  background: var(--primary);
  border: 3px solid var(--primary);
  border-radius: 6px;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.1s, color 0.1s, transform 0.05s;
  min-width: 48px;
  min-height: 48px;
}

.btn:hover {
  background: #b4d0fb;
  border-color: #b4d0fb;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.95);
  background: var(--accent);
  border-color: var(--accent);
}

.btn.small {
  padding: 6px 12px;
  font-size: 0.875rem;
  min-width: 40px;
  min-height: 40px;
}

.period {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 24px;
  padding: 12px;
  border: 2px dashed var(--muted);
  border-radius: var(--radius);
}

.period-label {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.period-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  min-width: 1.5em;
  text-align: center;
}

.actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

#reset-btn {
  background: var(--accent);
  border-color: var(--accent);
}

#reset-btn:hover {
  background: #f6a9bd;
  border-color: #f6a9bd;
}

#reset-btn:active {
  background: var(--primary);
  border-color: var(--primary);
}

@media (max-width: 480px) {
  .teams {
    flex-direction: column;
  }
  .board {
    padding: 16px;
  }
  .score {
    font-size: 2.5rem;
  }
  .title {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  var state = {
    scores: { a: 0, b: 0 },
    period: 1,
    history: []
  };

  var scoreA = document.getElementById('score-a');
  var scoreB = document.getElementById('score-b');
  var periodValue = document.getElementById('period-value');
  var periodBtn = document.getElementById('period-btn');
  var undoBtn = document.getElementById('undo-btn');
  var resetBtn = document.getElementById('reset-btn');

  function render() {
    scoreA.textContent = state.scores.a;
    scoreB.textContent = state.scores.b;
    periodValue.textContent = state.period;
    undoBtn.disabled = state.history.length === 0;
  }

  function addScore(team, points) {
    state.history.push({ team: team, points: points });
    state.scores[team] += points;
    render();
  }

  function undo() {
    var last = state.history.pop();
    if (!last) return;
    state.scores[last.team] -= last.points;
    render();
  }

  function nextPeriod() {
    if (state.period < 4) {
      state.period += 1;
      render();
    }
  }

  function reset() {
    state.scores.a = 0;
    state.scores.b = 0;
    state.period = 1;
    state.history = [];
    render();
  }

  var scoreButtons = document.querySelectorAll('.score-btn');
  for (var i = 0; i < scoreButtons.length; i++) {
    scoreButtons[i].addEventListener('click', function () {
      var team = this.getAttribute('data-team');
      var points = parseInt(this.getAttribute('data-points'), 10);
      addScore(team, points);
    });
  }

  periodBtn.addEventListener('click', nextPeriod);
  undoBtn.addEventListener('click', undo);
  resetBtn.addEventListener('click', reset);

  render();
})();
